      "path": "distill_kura/thinker.py",
      "content": "\"\"\"Model endpoints. One OpenAI-compatible client, three *roles*:\n\n    thinker  — picks index lines by meaning at recall time (small, fast, always-on)\n    brain    — the distiller's reader: finds what is worth keeping in raw journal\n    scribe   — the distiller's writer: turns evidence into a memory in the store's language\n\nDefault is ONE model wearing all three hats (`[models.thinker]` only).\nUpgrade path: give `brain` and/or `scribe` their own endpoint — a bigger local\nmodel, or an online API (any OpenAI-compatible `/chat/completions`; the key is\nread from the environment variable named in `api_key_env`, never from the file).\n\nReasoning-effort dialects differ between model families (`reasoning_effort`,\n`thinking_effort`, `enable_thinking`). A local inference server passes them through its\nchat template, which ignores what it does not know — that is why sending all of them at\nonce is safe there, and it matters because a model left at its default \"deep thinking\"\ncan burn the whole token budget on reasoning and return an empty answer.\n\nA STRICT OpenAI-compatible service is a different animal: an unknown top-level field is\na 400, not something to ignore. So the body shape is chosen by `dialect`:\n\n    vllm     (default) send chat_template_kwargs — local servers, vLLM, SGLang, llama.cpp\n    openai   omit it; send only fields the OpenAI schema defines\n    generic  the minimum: model, messages, temperature, max_tokens\n\nAnything that answers `POST <url>/chat/completions` in the OpenAI shape works. That is\nNOT the same as \"any provider\": a vendor's native API (Anthropic's, for instance) needs\nan OpenAI-compatible gateway in front of it, and its own URL will not do.\n\nOn a 400 the client retries ONCE with the `generic` body, because \"the server rejected a\nfield\" and \"the server is down\" are different problems and only one of them is worth\ngiving up on. Failures are recorded on the endpoint (`last_error`) rather than collapsing\ninto a bare `None`: an operator needs to tell a wrong key from a wrong URL from a wrong\nmodel name.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport urllib.error\nimport urllib.request\nfrom dataclasses import dataclass, field\n\n\ndef bearer_headers(api_key_env: str | None) -> dict:\n    \"\"\"`{\"Authorization\": \"Bearer <key>\"}` when the named variable is set and non-empty,\n    else `{}`. Empty counts as unset — the rule all three callers (ask, alive and\n    payforward._post) already applied separately, in three copies of the same block.\"\"\"\n    key = os.environ.get(api_key_env, \"\") if api_key_env else \"\"\n    return {\"Authorization\": f\"Bearer {key}\"} if key else {}\n\n\n@dataclass\nclass Endpoint:\n    # No built-in default: an unset url used to silently become 127.0.0.1:8000, so a\n    # half-written config sent traffic to whatever happened to be listening there.\n    url: str = \"\"\n    model: str = \"default\"\n    api_key_env: str | None = None\n    timeout: float = 120.0\n    temperature: float = 0.2\n    effort: str = \"low\"              # low | medium | high — mapped onto every dialect\n    thinking: bool = False           # for templates that only know enable_thinking\n    dialect: str = \"vllm\"            # vllm | openai | generic — see the module docstring\n    extra: dict = field(default_factory=dict)   # merged into the request body verbatim\n    name: str = \"thinker\"\n    last_error: str = \"\"             # why the last call failed, for health and logs\n    last_usage: dict | None = None   # usage from the last answered call, when reported\n\n    @classmethod\n    def from_dict(cls, d: dict, name: str, base: \"Endpoint | None\" = None) -> \"Endpoint\":\n        src = {**(base.__dict__ if base else {}), **{k: v for k, v in d.items() if v is not None}}\n        src.pop(\"name\", None)\n        known = {k: src[k] for k in cls.__dataclass_fields__ if k in src}\n        return cls(name=name, **known)\n\n    def template_kwargs(self) -> dict:\n        return {\"enable_thinking\": self.thinking,\n                \"reasoning_effort\": self.effort,\n                \"thinking_effort\": self.effort}\n\n    def _body(self, system: str, user: str, max_tokens: int, temperature: float | None,\n              dialect: str) -> dict:\n        body = {\n            \"model\": self.model,\n            \"messages\": [{\"role\": \"system\", \"content\": system},\n                         {\"role\": \"user\", \"content\": user}],\n            \"temperature\": self.temperature if temperature is None else temperature,\n            \"max_tokens\": max_tokens,\n        }\n        if dialect == \"vllm\":\n            body[\"chat_template_kwargs\"] = self.template_kwargs()\n            body.update(self.extra)\n        elif dialect == \"openai\":\n            body.update(self.extra)\n        return body                     # generic: the minimum, extras included nowhere\n\n    def _choice(self, system: str, user: str, max_tokens: int,\n                timeout: float | None, temperature: float | None) -> dict | None:\n        \"\"\"The raw `choices[0]` of one request, or None when the call did not produce\n        one. Every caller of this endpoint goes through here, so the retry ladder, the\n        `last_error` wording and the \"unconfigured is unreachable\" rule exist once —\n        `ask()` and `ask_full()` differ only in what they read off the reply, never in\n        how the call is made.\"\"\"\n        if not self.url:\n            self.last_error = \"no url configured\"\n            return None                 # unconfigured is unreachable, not \"somewhere else\"\n        self.last_usage = None\n        headers = {\"Content-Type\": \"application/json\", **bearer_headers(self.api_key_env)}\n        # The note rides the HTTP failure instead of being written to last_error here:\n        # written here it was a dead store — every exit path below reassigns last_error\n        # before returning, so no operator could ever see it. A missing key surfaces as\n        # a 401, and that is the message that needs to say the variable was never set.\n        key_note = (\"\" if not self.api_key_env or \"Authorization\" in headers\n                    else f\"; {self.api_key_env} is not set\")\n        for dialect in (self.dialect, \"generic\"):\n            try:\n                req = urllib.request.Request(\n                    self.url.rstrip(\"/\") + \"/chat/completions\",\n                    data=json.dumps(self._body(system, user, max_tokens, temperature,\n                                               dialect)).encode(),\n                    headers=headers)\n                with urllib.request.urlopen(req, timeout=timeout or self.timeout) as r:\n                    d = json.load(r)\n                self.last_usage = d.get(\"usage\") if isinstance(d.get(\"usage\"), dict) else None\n                choice = d[\"choices\"][0]\n                choice[\"message\"]           # the shape ask() has always demanded\n                self.last_error = \"\"\n                return choice\n            except urllib.error.HTTPError as e:\n                detail = \"\"\n                try:\n                    detail = e.read().decode()[:200]\n                except Exception:\n                    pass\n                self.last_error = f\"HTTP {e.code} ({dialect} body{key_note}): {detail}\"\n                # 400 usually means \"I do not know that field\". Worth one plainer attempt;\n                # anything else is a key, a model name or a server, and retrying is noise.\n                if e.code != 400 or dialect == \"generic\":\n                    return None\n            except (urllib.error.URLError, TimeoutError, OSError) as e:\n                self.last_error = f\"unreachable: {type(e).__name__}: {e}\"\n                return None\n            except (KeyError, ValueError, IndexError) as e:\n                self.last_error = f\"unexpected reply shape: {type(e).__name__}: {e}\"\n                return None\n        return None\n\n    def ask(self, system: str, user: str, max_tokens: int = 400,\n            timeout: float | None = None, temperature: float | None = None) -> str | None:\n        \"\"\"The answer text, or None when the call did not produce one.\n\n        None means \"degrade gracefully\", never \"the model said nothing\" — the reason is\n        left in `last_error` so an operator can tell a wrong key from a wrong URL from a\n        rejected field.\"\"\"\n        choice = self._choice(system, user, max_tokens, timeout, temperature)\n        if choice is None:\n            return None\n        m = choice[\"message\"]\n        # some servers put thinking in `reasoning`/`reasoning_content`; content wins\n        return (m.get(\"content\") or m.get(\"reasoning_content\")\n                or m.get(\"reasoning\") or \"\").strip()\n\n    def ask_full(self, system: str, user: str, max_tokens: int = 400,\n                 timeout: float | None = None,\n                 temperature: float | None = None) -> dict | None:\n        \"\"\"The same one request, taken apart instead of flattened: `content` (what a\n        user would actually see), `reasoning` (whatever the server put in\n        `reasoning_content`/`reasoning`) and `finish_reason`.\n\n        `ask()` falls back to the reasoning when the content is empty; that is a\n        thinker-side kindness — recall wants the best text going. A measurement wants\n        the opposite: a model that spent its whole budget thinking and said nothing\n        answered nothing, and a reply cut at the token cap must be visible as cut.\n        Keeping the two apart is why this is a separate method rather than a flag.\"\"\"\n        choice = self._choice(system, user, max_tokens, timeout, temperature)\n        if choice is None:\n            return None\n        m = choice[\"message\"]\n        return {\"content\": (m.get(\"content\") or \"\").strip(),\n                \"reasoning\": (m.get(\"reasoning_content\") or m.get(\"reasoning\") or \"\").strip(),\n                \"finish_reason\": choice.get(\"finish_reason\")}\n\n    def alive(self) -> bool:\n        if not self.url:\n            return False\n        try:\n            req = urllib.request.Request(self.url.rstrip(\"/\") + \"/models\",\n                                         headers=bearer_headers(self.api_key_env))\n            urllib.request.urlopen(req, timeout=5).read()\n            return True\n        except Exception:\n            return False\n\n\n@dataclass\nclass Models:\n    thinker: Endpoint\n    brain: Endpoint\n    scribe: Endpoint\n\n    @classmethod\n    def from_config(cls, cfg: dict | None) -> \"Models\":\n        cfg = cfg or {}\n        thinker = Endpoint.from_dict(cfg.get(\"thinker\", {}), \"thinker\")\n        # Upgrade path: brain/scribe inherit thinker unless overridden.\n        brain = Endpoint.from_dict(cfg.get(\"brain\", {}), \"brain\", base=thinker)\n        if \"brain\" in cfg and \"effort\" not in cfg[\"brain\"]:\n            brain.effort = \"medium\"          # listing work goes quiet on `low`\n        scribe = Endpoint.from_dict(cfg.get(\"scribe\", {}), \"scribe\", base=brain)\n        if \"scribe\" in cfg and \"temperature\" not in cfg[\"scribe\"]:\n            scribe.temperature = 0.4\n        return cls(thinker, brain, scribe)\n\n    def describe(self) -> dict:\n        def same(a: Endpoint, b: Endpoint) -> bool:\n            return a.url == b.url and a.model == b.model\n        shared = same(self.brain, self.thinker) and same(self.scribe, self.thinker)\n        return {r: {\"url\": e.url, \"model\": e.model, \"effort\": e.effort,\n                    \"dialect\": e.dialect, \"api_key_env\": e.api_key_env,\n                    \"last_error\": e.last_error}\n                for r, e in ((\"thinker\", self.thinker), (\"brain\", self.brain),\n                             (\"scribe\", self.scribe))} | {\"single_model\": shared}\n"
    },
    {
      "path": "docs/TRUST.md",
      "content": "# Trust zones — what a store boundary is, and what it is not\n\nRead this before putting anything you would not publish into a kura.\n\n## The claim, stated exactly\n\nSeveral kura behind one server are **independent as routing**: separate memories,\nseparate index, separate distiller watermark, separate model profile if you configure\none. A bound agent cannot wander between them, and a name cannot become a path.\n\nThey are **not a confidentiality boundary.** The server has no authentication. Any\nprocess that can reach its port can name any store it holds; any process that can read\nthe directory can read the memories. The bound-agent machinery keeps a *model* inside\nits lane — it does not keep a *process* out.\n\nBoth halves matter. The first is what makes modes useful. The second is why the\nfollowing is not optional.\n\n## The rule\n\n**One trust level per process.** Do not put a private store and a less-trusted store in\nthe same registry, and do not point a less-trusted agent at a server that holds one.\n\n```\n                 ┌── shared / neutral ──────────┐   ┌── private ─────────────────┐\n  config         │ kura-shared.toml             │   │ kura-private.toml          │\n  process        │ port 8085 (or a unix socket) │   │ port 8086, different user   │\n  stores         │ shared-notes, scratch        │   │ project-alpha               │\n  models         │ any endpoint you like        │   │ a local endpoint only       │\n  agents         │ any                          │   │ the private preset only     │\n                 └──────────────────────────────┘   └────────────────────────────┘\n```\n\nConcretely:\n\n- A separate `kura.toml` per trust level. **Do not even list a private store's name in a\n  shared config** — a name, a label and a memory count are themselves information.\n- A separate process and port per trust level. A unix domain socket behind a reverse\n  proxy is better than a TCP port if you have the option.\n- A separate OS user, or a container, where the levels really differ. File permissions\n  are the boundary that actually holds.\n- Never mount a private store's directory into a less-trusted process, workspace or\n  container.\n- Never put a private config inside a repository a less-trusted agent can read.\n- Bind every agent: `store: \"…\"` in the plugin (which now binds by itself), or\n  `KURA_STORE=…` for the MCP bridge.\n- Set `write_policy` deliberately per store — see below.\n\n## Why not one process with access control\n\nA permission layer inside a single process would have to be trusted by everything in\nthat process, and this is a small dependency-free core whose value is that you can read\nall of it. An OS user boundary is stronger, older and easier to verify than any token\ncheck we could add. If you need multi-tenant serving with authentication, put a proxy in\nfront and keep one kura process per tenant behind it.\n\n## Write authority\n\n`write_policy` decides who may add a memory:\n\n| policy | a tool call or the CLI | the distiller's verified pour |\n|---|---|---|\n| `direct-allowed` (default) | yes | yes |\n| `distiller-only` | **no** | yes |\n| `frozen` | no | **no** |\n\n`frozen` means **no memory and no index changes**. The workshop under `_still/` may still\nbe written — the read log, and a woven cloth if you point `cloth_path` outside the store\n— because those are derived artifacts, not memory. A frozen store refuses to have a cloth\nwoven *inside* it at all, so an archive that should keep a resident map needs\n`cloth_path` set somewhere else.\n\nOne more canonical change has its own door, and it is not on that table because no\npolicy widens it: `Store.retire(old, new, manifest_hex)` writes the retirement face onto\na superseded memory's index line (docs/DESIGN.md §8). There is no direct variant of it.\nIt requires an evidence manifest that verifies against its own hash and carries a\nUSER-class quote naming the old memory, so a tool call cannot reach it under any\n`write_policy`, and `frozen` refuses it like everything else. Naming the old memory is\nthe floor, not the proof: the same manifest must also carry ONE [USER] quote in which\nthe human retires that memory AND names this successor — proposed ≠ proven, and a model\nproposing a `superseded` tag (or the gate refusing it) counts for nothing. Only the\nhuman's explicit old → new sentence writes `現在は [[new]]`; anything less is refused\nwith \"no explicit succession in the human's words\". The door re-proves this itself\nrather than trusting the distiller that knocked. Many false negatives at first are\nacceptable; a wrong successor in canonical is not. Its limit is the gate\nmark's limit: the manifests sit beside the memories, so this stops a tool with a file\nhandle, not a principal with the filesystem.\n\nThe MCP bridge can additionally keep a client-side audit line per direct write\n(`KURA_WRITE_LOG`, one JSONL record per successful `kura_remember`). It is a record,\nnot a permission: the write has already happened by the time it is logged.\n\n`distiller-only` is the right setting for anything an agent reads from constantly: every\nmemory then has to pass the evidence gate, and a model with a spare tool call cannot\nwrite a fact into the store.\n\n**What that door actually checks.** The gate signs each draft it stages, and the pour\nverifies the signature, so a file dropped into `_still/drafts/` by hand does not pour and\na staged draft edited afterwards stops pouring. Be clear about the limit: the key lives\nnext to the drafts, so a principal who can write that directory can usually read the key\ntoo. This stops an agent with a file tool, and it stops an accident. It does not stop\nsomeone who has the filesystem — nothing in this process can, which is the point of the\nsection above. `frozen` is for an archive you are keeping but not growing.\n\nThe deprecated `readonly = true` maps to `distiller-only`, which is what it always\nclaimed to mean. It used to refuse the pour as well, so a store advertised as\ndistiller-maintained was frozen solid and nothing said so.\n\n## Journal intake is a boundary too\n\nSeparating memories buys nothing if both stores drink from the same journal. With more\nthan one store configured, the distiller **refuses to guess**: bind each store to its\nown root.\n\n```toml\n[stores.maker.distill.journals]\ndsh = \"~/dsh/sessions-maker\"\n\n[stores.eq.distill.journals]\ndsh = { root = \"~/dsh/sessions\", exclude_glob = [\"**/maker-*/**\"] }\n```\n\nThe registry also refuses, at load, a journal root that contains a store: the distiller\nwould re-ingest memories as raw material and file model-written text as the human's\nwords, which breaks the one guarantee the evidence gate gives. Override with\n`[server] allow_path_overlap = true` only if you understand exactly why you want it.\n\n## Model intake is a boundary too\n\nOne shared `thinker` sees **every** store's entire index on every recall, and one shared\n`brain`/`scribe` sees every journal and every draft. Separating directories does nothing\nabout that. Bind a profile:\n\n```toml\n[model_profiles.private.thinker]\nurl = \"http://127.0.0.1:8100/v1\"\nmodel = \"private-thinker\"\n\n[stores.project]\npath = \"~/kura/project\"\nmodel_profile = \"private\"\n```\n\nAn undefined profile is a load error, never a quiet fall back to the shared endpoint —\nthat fallback is exactly how a private index reaches a model it was never meant to see.\n\nRemember what an endpoint is: a hosted API sees whatever you send it. \"Local model\" is a\nproperty of the URL, not of the config key.\n\n## What is checked for you, at load\n\nThe registry refuses to start when any of these is true:\n\n- two stores resolve to the same directory (including via a symlink)\n- one store lives inside another\n- a journal root and a store root overlap\n- a mode names a different store than one that shares its name\n- a store table carries an unknown key or a wrong type\n- a store names a model profile that does not exist\n\nAnd at runtime: a name can only resolve to a memory the store holds, an explicit read is\nexact, and a file whose real path leaves the store is excluded and reported by `doctor()`\nas `escaping`.\n\n## What a path check cannot see: hardlinks\n\n`contained()` resolves symlinks, and a symlink out of the store is excluded. A **hardlink\nis different in kind**: it is a first-class name for an inode, not a pointer to another\npath, so `realpath()` stays inside the store and the file genuinely *is* a file in the\nstore. Content placed there is served — correctly, by the rules — and it keeps serving\nthe target's future edits.\n\n```bash\nln  /other/store/secret.md  ~/kura/public/looks-innocent.md   # served by `public`\nln -s /other/store/secret.md ~/kura/public/looks-innocent.md  # excluded, reported\n```\n\nThis is not a gap in name resolution; it is what \"putting a file into the store\ndirectory\" means. The boundary for it is **filesystem permissions** — which is the whole\nreason for one trust level per user and process. `doctor()` reports every memory with\n`st_nlink > 1` under `hardlinked` so it is at least visible; they are not excluded,\nbecause snapshot backups and `rsync --link-dest` give every file a second link and a\nstore that went dark under a backup tool would be the worse failure.\n\nIf it matters to you: keep the stores on separate filesystems (a hardlink cannot cross\none), or under separate users.\n\n## Tags, annotations and the learned profile do not widen anything\n\nThree things were added around a memory — tags, three curation sentences, and an\noptional `profile.md` — and none of them changes the claim above. They are files in\nthe store directory and fall under the same boundary as the memories: a process that\ncan read the store can read them, a process that cannot, cannot. The write side keeps\nits two doors: a tag goes on through `annotate_direct` (refused on `distiller-only`)\nor `annotate_verified` (the distiller, with evidence in the manifest), and `frozen`\nrefuses both. The verified door also **signs** the curation it leaves — a\n`curation_mark` over slug, tags and the three sentences, with the same per-store key\nthe gate signs drafts with — so on a `distiller-only` store a tag written into the\nfile by hand shows in `doctor` as `unsigned`, and one edited after the fact as\n`tampered`. The reader still reads the tag; the mark changes what `doctor` says, not\nwhat recall returns. Its limit is the gate mark's limit: the key sits beside the\nmemories, so this is a guard against a tool with a file handle, not against a\nprincipal with the filesystem. The profile is read by that store's distiller only and drafted from that\nstore's memories only; it is never carried into another store's prompt. Nothing here\nis a permission layer, and nothing here should be read as one.\n\n## What is still on you\n\n- process, user and file-permission separation (this is what stops a hardlink, a copy,\n  or anything else placed directly into a store directory)\n- not listing private store names in shared configs\n- choosing endpoints that match the store's trust level\n- backing a kura up to its **own private** repository, never the code repository\n"
    },
    {
      "path": "dsh-plugin/lib/index.js",
      "content": "/**\n * dsh-distill-kura — the 蔵 (kura) as a DeepSeek Harness plugin.\n *\n *   model ── ctx.tools ── this plugin ── HTTP ── distill-kura server ── one or more kura\n *\n * Why a native plugin and not only the MCP bridge: a plugin can bind memory to the\n * agent's MODE. DSH switches persona and tools by agent preset; mount this row inside\n * a preset with `store: \"eq\"` and that preset remembers from the EQ kura, while the\n * maker preset remembers from the maker kura. One switch moves persona (the harness's\n * plane) and memory (ours) together.\n *\n * The MCP bridge (`python3 -m distill_kura.mcp`) does the same job for hosts that only\n * speak MCP. Use one or the other, not both — two mounts put two copies of the same\n * tool in front of the model.\n *\n * The shape of this file follows the harness's own rules for plugins:\n *   1. **Config errors fail LOUDLY at load.** A silently skipped plugin looks exactly\n *      like a working one. Anything unusable throws here, naming the offending value.\n *   2. **Registration must be reversible.** `register()` and `guard()` return disposers;\n *      both go on `ctx.effect()`, so unloading leaves no debris.\n *   3. **Policy does not live inside a tool.** The one irreversible action (writing a\n *      memory) is refused by `ctx.tools.guard()`, which is monotonic — no other\n *      listener can overturn a denial.\n *   4. **ASCII tool names, human descriptions.** A tool name is a function-calling key;\n *      non-ASCII breaks some endpoints. The description is where \"when to call this\"\n *      and \"what an empty answer means\" belong — it is all the model knows.\n *   5. **Every result carries its context.** Each answer says which kura replied and how\n *      it was retrieved. `how=words` means the thinker was unreachable and quality\n *      quietly degraded; hiding that is worse than the degradation.\n *\n * Optional parameters must NOT carry `required: false` — the schema compiler rejects\n * it (\"required must be true when present\"). Omit the key instead.\n *\n * ── the resident map ────────────────────────────────────────────────────────────\n * Tools answer \"what do you know about X?\" only once the agent has decided to ask. This\n * plugin also registers a system-prompt SECTION holding the whole index, so the agent\n * can see what is known without asking — and, more importantly, can see what is *not*.\n *\n * Two hard constraints from the harness, both verified in its own .d.ts:\n *\n *   1. `section({ text })` may be a function, but it is **synchronous**\n *      (`text: string | ((context) => string)`), and it is called on every prompt\n *      assembly — that is, every model STEP, not every turn. Returning a Promise puts\n *      \"[object Promise]\" in the prompt. So the map is fetched in the BACKGROUND and the\n *      provider hands back whatever is cached, instantly.\n *\n *   2. Sections concatenate in ascending `order`; -100 is the harness identity, 0 the\n *      persona, 100-199 tool guidance. We default to **-50: before the persona**, and\n *      that is a cache decision, not an aesthetic one. A prefix cache is lost from the\n *      first changed byte onward. The persona commonly embeds a clock (`{{now}}` via\n *      dsh-now), so it changes every minute; anything after it is re-priced every\n *      minute too. The map is the largest block in the prompt and changes a few times a\n *      day, so it belongs in front of the thing that ticks.\n *      If nothing volatile precedes the tool sections in your deployment, a late order\n *      (200) is cheaper when the map itself changes. Set `promptOrder` and know why.\n */\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\n\nconst name = \"distill-kura\";\nconst inject = [\"tools\", \"systemPrompt\"];\n\n/** Config: `{ url, store, label, readonly, allowSwitch, timeoutMs }` — all optional. */\nconst Config = undefined;\n\nconst DEFAULTS = {\n  url: \"http://127.0.0.1:8085\",\n  store: \"\",           // \"\" = the server's default; set it per preset to bind a mode\n  label: \"the kura\",\n  readonly: true,      // writing belongs to the distiller's evidence gate\n  // allowSwitch has NO fixed default: it follows `store`. A preset that names a store\n  // means to be bound to it, and having to remember a second flag to get that is a\n  // default that fails open. Set it explicitly to override.\n  allowSwitch: undefined,\n  timeoutMs: 120_000,\n  prefill: true,       // keep the index resident in the system prompt\n  promptOrder: -50,    // before the persona — see the header note on prefix caches\n  refreshMs: 120_000,  // how often the background refresh re-reads the map\n};\n\nconst TEXT = {\n  schema: { type: \"string\" },\n  render: (_args, value) => [{ type: \"text\", text: value }],\n};\n\nfunction settle(config) {\n  const c = { ...DEFAULTS, ...(config || {}) };\n  if (c.allowSwitch === undefined) c.allowSwitch = c.store === \"\";\n  // Rule 1: refuse loudly. A typo here must never present as \"memory is empty today\".\n  // A bare \"http://\" passes /^https?:\\/\\// but trims to \"http:\" and fetch throws a\n  // TypeError later — require a host: at least one non-slash, non-space character\n  // after the scheme.\n  if (typeof c.url !== \"string\" || !/^https?:\\/\\/[^/\\s]/.test(c.url)) {\n    throw new Error(`distill-kura: url must be an http(s) URL, got ${JSON.stringify(c.url)}`);\n  }\n  if (typeof c.store !== \"string\") {\n    throw new Error(`distill-kura: store must be a string (store or mode name), got ${JSON.stringify(c.store)}`);\n  }\n  if (typeof c.label !== \"string\" || !c.label) {\n    throw new Error(`distill-kura: label must be a non-empty string, got ${JSON.stringify(c.label)}`);\n  }\n  for (const k of [\"readonly\", \"allowSwitch\"]) {\n    if (typeof c[k] !== \"boolean\") {\n      throw new Error(`distill-kura: ${k} must be a boolean, got ${JSON.stringify(c[k])}`);\n    }\n  }\n  if (!Number.isFinite(c.timeoutMs) || c.timeoutMs <= 0) {\n    throw new Error(`distill-kura: timeoutMs must be a positive number, got ${JSON.stringify(c.timeoutMs)}`);\n  }\n  if (typeof c.prefill !== \"boolean\") {\n    throw new Error(`distill-kura: prefill must be a boolean, got ${JSON.stringify(c.prefill)}`);\n  }\n  if (!Number.isFinite(c.promptOrder)) {\n    throw new Error(`distill-kura: promptOrder must be a number, got ${JSON.stringify(c.promptOrder)}`);\n  }\n  if (!Number.isFinite(c.refreshMs) || c.refreshMs < 5_000) {\n    // Below a few seconds this hammers the kura for a map that changes a few times a day.\n    throw new Error(`distill-kura: refreshMs must be a number >= 5000, got ${JSON.stringify(c.refreshMs)}`);\n  }\n  c.url = c.url.replace(/\\/+$/, \"\");\n  return c;\n}\n\n/** 304 from a conditional GET: nothing changed, and nothing was transferred. */\nconst UNCHANGED = Symbol(\"unchanged\");\n\nasync function call(cfg, method, path, body, signal, headers = {}) {\n  const ac = new AbortController();\n  const onAbort = () => ac.abort();\n  signal?.addEventListener(\"abort\", onAbort, { once: true });\n  const timer = setTimeout(() => ac.abort(), cfg.timeoutMs);\n  try {\n    const res = await fetch(cfg.url + path, {\n      method,\n      signal: ac.signal,\n      headers: { \"Content-Type\": \"application/json\", ...headers },\n      body: body === undefined ? undefined : JSON.stringify(body),\n    });\n    if (res.status === 304) return UNCHANGED;\n    const text = await res.text();\n    let data;\n    try {\n      data = JSON.parse(text);\n    } catch {\n      throw new Error(`kura answered non-JSON (${res.status}): ${text.slice(0, 200)}`);\n    }\n    if (!res.ok) throw new Error(`kura ${res.status}: ${data.error || text.slice(0, 200)}`);\n    return data;\n  } finally {\n    clearTimeout(timer);\n    signal?.removeEventListener(\"abort\", onAbort);\n  }\n}\n\nconst q = (store) => (store ? `?store=${encodeURIComponent(store)}` : \"\");\n// The kura this session is speaking from: a bound preset never leaves its own.\nconst activeStore = (cfg, state) => (state.bound ? cfg.store : state.current);\n// \"No map for this store\" — the one shape, so a reader cannot wonder whether the\n// three places that build it differ on purpose.\nconst emptyMap = (store, error) =>\n  ({ ok: false, store, served: \"\", text: \"\", etag: \"\", at: 0, ...(error ? { error } : {}) });\nconst head = (store, extra) => `[kura: ${store || \"default\"}${extra ? \" \" + extra : \"\"}]`;\n\n/**\n * Is `served` the store that the selector `sel` actually names?\n *\n * `?store=` accepts a store OR a mode name, and the server answers with the STORE it\n * resolved to. Comparing that name against the selector we sent made every mode look\n * like a server answering for the wrong kura: a preset bound to `talking` (a mode for\n * the `eq` kura) threw its own map away on every refresh and wore the MISSING note\n * forever, while recall — which sends the same selector — answered perfectly.\n *\n * Deliberately NOT \"believe whatever the answer says\". The check this feeds is the one\n * that catches a server ignoring the selector entirely, and it must keep failing\n * closed, so the resolution is read from /stores — the same table kura_use validates\n * against — and only a mode that really does target `served` is accepted. It is cached\n * because a mode's target does not move while the server is up.\n */\nasync function resolves(cfg, state, sel, served, signal) {\n  if (state.resolved.get(sel) === served) return true;\n  const d = await call(cfg, \"GET\", \"/stores\", undefined, signal);\n  if (((d.modes || {})[sel]) !== served) return false;\n  state.resolved.set(sel, served);\n  return true;\n}\n\n/**\n * The resident map, kept warm out of band.\n *\n * The prompt provider is synchronous and runs on every step, so it must never wait on\n * the network — it reads `state.map.text` and returns. This object is the only thing\n * standing between \"the map is a little stale\" and \"the agent stalls on every token\".\n *\n * When the kura is unreachable we serve an explicit note, never an empty string. An\n * agent handed nothing concludes that nothing is remembered, which is a stronger and\n * more damaging claim than \"the memory is down\".\n */\nfunction mapCache(cfg, state) {\n  const missing = () =>\n    `<<<KURA-MAP store=${state.current || \"default\"}>>>\\n` +\n    `${cfg.label} keeps a long-term memory, but its index could not be read just now.\\n` +\n    `The map is MISSING, not empty — do not conclude that nothing is remembered.\\n` +\n    `It may simply not have arrived yet (it is fetched in the background, once per\\n` +\n    `session and then on a timer). Call kura_map to read it now, or kura_recall to ask\\n` +\n    `a question directly. If both fail, say the memory is unavailable.\\n` +\n    `<<<END KURA-MAP>>>\\n`;\n\n  return {\n    // The map ALWAYS carries the store it describes, and it is only served while that\n    // store is the one being recalled from. Without this, a failed switch left the\n    // previous kura's index in the prompt while recall went to the new one: the agent\n    // read one household's map and answered from another's, and the staleness grace\n    // period kept it there for minutes.\n    // A map is \"for\" a store under two names: the one we asked for (`store`, which may\n    // be \"\" meaning the server's default) and the one the server said it answered for\n    // (`served`). Treating those as different made a map fetched for the default store\n    // a stranger to the same store named explicitly, so `kura_use(\"maker\")` on a\n    // default-is-maker server threw the map away and transferred it again in full.\n    isFor: (want) => state.map.ok && (state.map.store === want || state.map.served === want),\n    text() {\n      return this.isFor(activeStore(cfg, state)) ? state.map.text : missing();\n    },\n    invalidate(target) {\n      if (state.map.store !== target && state.map.served !== target) {\n        state.map = emptyMap(target);\n      }\n    },\n    async refresh() {\n      const target = activeStore(cfg, state);\n      // A timer refresh for store A and a kura_use-triggered refresh for store B can\n      // interleave: A's request is still in flight when current moves to B, and A's\n      // late failure then downgraded B's resident map (ok=false) — or a late 200\n      // installed A's over B's. Only the newest refresh may write state.map.\n      const gen = (this.gen = (this.gen || 0) + 1);\n      this.invalidate(target);\n      try {\n        // Conditional: the map is the largest thing we fetch and it changes a few times\n        // a day, while this runs every couple of minutes.\n        const d = await call(cfg, \"GET\", \"/prefill\" + q(target), undefined, undefined,\n          this.isFor(target) && state.map.etag\n            ? { \"If-None-Match\": `\"${state.map.etag}\"` } : {});\n        // A newer refresh superseded this one: bail without touching state.map, so a\n        // stale outcome cannot clobber whatever map is resident now.\n        if (gen !== this.gen) return false;\n        if (d === UNCHANGED) {\n          state.map.at = Date.now();\n          return true;\n        }\n        // The server names the STORE it answered for, and the selector may have been a\n        // MODE — a different name is then the resolution, not a betrayal. Only a name\n        // that /stores does not confirm means the map is not ours to show.\n        if (d.store !== undefined && target && d.store !== target) {\n          const legit = await resolves(cfg, state, target, d.store);\n          // Another await, another chance to have been superseded.\n          if (gen !== this.gen) return false;\n          if (!legit) {\n            state.map = emptyMap(target, `asked for ${target}, served ${d.store}`);\n            return false;\n          }\n        }\n        // Only swap when the content actually differs: replacing the string with an\n        // identical one is free, but replacing it with a *re-ordered* one is not, and\n        // this makes the etag the single source of truth for \"did the map change\".\n        if (d.etag !== state.map.etag || !state.map.ok) {\n          state.map = { ok: true, store: target, served: d.store || target, text: d.text,\n                        etag: d.etag, at: Date.now(), stats: d };\n        } else {\n          state.map.at = Date.now();\n        }\n        return true;\n      } catch (err) {\n        // Only the still-current refresh may downgrade: a stale failure must not mark\n        // the resident map — which now describes a newer store — as failed.\n        if (gen !== this.gen) return false;\n        // A staleness grace period is only ever granted to the store the map is FOR.\n        state.map.ok = this.isFor(target) && Date.now() - state.map.at < cfg.refreshMs * 5;\n        state.map.error = String(err && err.message ? err.message : err);\n        return false;\n      }\n    },\n  };\n}\n\n/**\n * Strip the `store` parameter from a bound agent's tools.\n *\n * A bound agent cannot use it — `target()` ignores it — so leaving it in the schema\n * only invites the model to try, and every turn pays for describing a parameter that\n * does nothing. (Least disclosure, not a security boundary: a process that can reach\n * the HTTP port can name any store. See docs/TRUST.md.)\n */\nfunction withoutStoreParam(tool) {\n  if (!tool.parameters || !(\"store\" in tool.parameters)) return tool;\n  const { store, ...rest } = tool.parameters;\n  return { ...tool, parameters: rest };\n}\n\nfunction tools(cfg, state) {\n  const target = (store) => (state.bound ? cfg.store : store || state.current);\n\n  // Registration order is the schema order a small model sees; the guidance says\n  // glance first — the confirmation door — with read and recall after it.\n  const list = [\n    defineTool({\n      name: \"kura_glance\",\n      description:\n        `Confirm ONE memory from ${cfg.label} by its slug — the exact index line, the ` +\n        `verified KEEP sentence and its [[links]], targeting ~150 tokens (the ` +\n        `recognition line and KEEP are never cut; links are trimmed first). Call it ` +\n        `when you recognise a slug on the resident map or from recall and want to be ` +\n        `sure it is the right memory before reading the whole thing. An unknown slug ` +\n        `simply says there is no memory by that name — a confirmation, not a search.`,\n      parameters: {\n        slug: { type: \"string\", description: \"Memory slug, without .md\", required: true },\n        store: { type: \"string\", description: \"Which kura. Omit for the current one.\" },\n      },\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(args, exec) {\n        const to = target(args.store);\n        let d;\n        try {\n          d = await call(cfg, \"GET\",\n            `/glance/${encodeURIComponent(args.slug)}` + q(to), undefined, exec?.signal);\n        } catch (e) {\n          // Same 404-by-design promise as kura_read: an unknown slug is \"no such\n          // memory\", not \"the kura is unreachable\".\n          if (/^kura 404\\b/.test(String(e && e.message))) {\n            return `${head(to)}\\n(no memory called ${args.slug})`;\n          }\n          throw e;\n        }\n        return `${head(to)}\\n` + (d.text || `(no memory called ${args.slug})`);\n      },\n    }),\n\n    defineTool({\n      name: \"kura_read\",\n      description:\n        `Read one whole memory from ${cfg.label} by its slug. Use after kura_glance (or ` +\n        `kura_recall) when the summary is not enough and you need the full text. An unknown ` +\n        `slug simply says so.`,\n      parameters: {\n        slug: { type: \"string\", description: \"Memory slug, without .md\", required: true },\n        store: { type: \"string\", description: \"Which kura. Omit for the current one.\" },\n      },\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(args, exec) {\n        const to = target(args.store);\n        let d;\n        try {\n          d = await call(cfg, \"GET\",\n            `/memory/${encodeURIComponent(args.slug)}` + q(to), undefined, exec?.signal);\n        } catch (e) {\n          // The server answers an unknown slug with 404 by design (EXACT reads).\n          // The tool promised \"an unknown slug simply says so\" — keep that promise.\n          if (/^kura 404\\b/.test(String(e && e.message))) {\n            return `${head(to)}\\n(no memory called ${args.slug})`;\n          }\n          throw e;\n        }\n        return `${head(to)}\\n` + (d.text || `(no memory called ${args.slug})`);\n      },\n    }),\n\n    defineTool({\n      name: \"kura_recall\",\n      description:\n        `Recall from ${cfg.label} — long-term memory retrieved by MEANING, not keywords, then ` +\n        `walking the [[links]] between memories. Use it when you cannot tell WHICH memory the ` +\n        `question is about — the fallback when no slug on the map or in the conversation clearly ` +\n        `fits, not the first door. An empty answer means it is not remembered yet — say so ` +\n        `plainly instead of inventing something to fill the gap.` +\n        (state.bound ? ` This agent is bound to the '${cfg.store}' kura.` : \"\"),\n      parameters: {\n        question: {\n          type: \"string\",\n          description: \"What you want to remember, as a natural question\",\n          required: true,\n        },\n        hops: { type: \"integer\", description: \"How many [[link]] hops to walk (default 1)\" },\n        store: {\n          type: \"string\",\n          description: \"Ask a different kura by store or mode name. Omit for the current one.\",\n        },\n      },\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(args, exec) {\n        const to = target(args.store);\n        const d = await call(cfg, \"POST\", \"/recall\" + q(to),\n          { question: args.question, hops: args.hops ?? 1 }, exec?.signal);\n        // \"Degraded\" has one meaning, and it is not \"anything but the usual tier\": the\n        // thinker was unreachable and the pick fell back to word overlap (`how` =\n        // \"words(...)\"). Marking every other answer degraded cried wolf over the two\n        // that are working exactly as designed — tier zero's deterministic 2 ms hit\n        // (`fastpath`), and `meaning→none`, the thinker reading the whole index and\n        // honestly naming nothing. An agent that learns to discount the ⚠ stops\n        // noticing the one time the quality really did drop.\n        const how = String(d.how || \"?\");\n        const shown = how.startsWith(\"words\") ? `${how}  ⚠ degraded` : how;\n        return (\n          `${head(d.store || to, `${d.elapsed_s}s / ${shown}`)}\\n` +\n          `picked: ${JSON.stringify(d.picked)}\\nwalked: ${JSON.stringify(d.walked)}\\n\\n` +\n          (d.context || \"(nothing recalled — not remembered yet)\")\n        );\n      },\n    }),\n\n    defineTool({\n      name: \"kura_doctor\",\n      description:\n        `Health of ${cfg.label}: memory count, resolved and dead [[links]], islands nothing ` +\n        `links to, index drift. Call when recall behaves oddly, or when asked about the memory ` +\n        `system itself.`,\n      parameters: {\n        store: { type: \"string\", description: \"Which kura. Omit for the current one.\" },\n      },\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(args, exec) {\n        return JSON.stringify(\n          await call(cfg, \"GET\", \"/doctor\" + q(target(args.store)), undefined, exec?.signal), null, 1);\n      },\n    }),\n\n  ];\n\n  if (!state.bound) {\n    list.push(defineTool({\n      name: \"kura_list\",\n      description:\n        \"List the kura this server holds, how many memories each has, and which agent mode maps \" +\n        \"to which. Call it when unsure which memory you are speaking from, or before switching.\",\n      parameters: {},\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(_args, exec) {\n        const d = await call(cfg, \"GET\", \"/stores\", undefined, exec?.signal);\n        // This tool is only registered when the session is not bound, so there is\n        // no bound branch to take here.\n        const cur = state.current || d.default;\n        const rows = Object.entries(d.stores || {}).map(([n, s]) => {\n          const modes = Object.entries(d.modes || {}).filter(([, t]) => t === n).map(([m]) => m);\n          return `  ${n === cur ? \"*\" : \"·\"} ${n}: ${s.label} — ${s.memories} memories` +\n            (modes.length ? `, modes=${JSON.stringify(modes)}` : \"\") +\n            // The STORE's policy, from the server. This plugin's own `readonly` only\n            // hides the write tool; it does not make the store refuse anything.\n            (s.write_policy && s.write_policy !== \"direct-allowed\" ? ` [${s.write_policy}]` : \"\");\n        });\n        return [`current: ${cur}`, ...rows].join(\"\\n\");\n      },\n    }));\n  }\n\n  if (cfg.prefill) {\n    list.push(defineTool({\n      name: \"kura_map\",\n      description:\n        `Show the whole index of ${cfg.label} — every memory's one-line trigger, in one ` +\n        `answer. Use it when you need to see WHAT EXISTS rather than look something up: ` +\n        `before saying a thing was never discussed, when choosing which memory to open, ` +\n        `or right after switching kura. The map is normally already in your context; ` +\n        `call this if it is missing or you suspect it is out of date.`,\n      parameters: {\n        store: { type: \"string\", description: \"Which kura. Omit for the current one.\" },\n      },\n      output: TEXT,\n      isConcurrencySafe: () => true,\n      async execute(args, exec) {\n        const to = target(args.store);\n        const d = await call(cfg, \"GET\", \"/prefill\" + q(to), undefined, exec?.signal);\n        // Same served-store check as refresh(), mode resolution included: a failed\n        // /stores lookup counts as \"not confirmed\", so this door also fails closed.\n        if (d.store !== undefined && to && d.store !== to &&\n            !(await resolves(cfg, state, to, d.store, exec?.signal).catch(() => false))) {\n          return `${head(to)}\\n` +\n            `(the server answered for a different kura (${d.store}); the map for ${to} could not be read)`;\n        }\n        return d.text;\n      },\n    }));\n  }\n\n  if (cfg.allowSwitch && !state.bound) {\n    list.push(defineTool({\n      name: \"kura_use\",\n      description:\n        \"Switch which kura the following calls read from, for the rest of this session. Use when \" +\n        \"the work changes character — building something versus talking something through. Only \" +\n        \"the memory moves: persona and tools belong to the agent preset, so a full mode change \" +\n        \"is a preset change.\",\n      parameters: {\n        store: { type: \"string\", description: \"Store or mode name\", required: true },\n      },\n      output: TEXT,\n      async execute(args, exec) {\n        const d = await call(cfg, \"GET\", \"/stores\", undefined, exec?.signal);\n        const known = new Set([...Object.keys(d.stores || {}), ...Object.keys(d.modes || {})]);\n        if (!known.has(args.store)) {\n          return `No kura called '${args.store}'. Known: ${JSON.stringify([...known])}`;\n        }\n        state.current = args.store;\n        // The listing already says which store a mode targets, so record it here and\n        // the refresh below does not have to ask for the same table again.\n        if ((d.modes || {})[args.store]) state.resolved.set(args.store, d.modes[args.store]);\n        // Swap the resident map too, and say so honestly when it could not be fetched:\n        // recalling from one kura while wearing another's index is the worst of both.\n        const got = state.cache ? await state.cache.refresh() : true;\n        return `${head(state.current)} Now recalling from '${args.store}'. ` +\n          (got ? \"\" : \"⚠ its index could not be read, so you are carrying no map for it. \") +\n          `(Memory only — the persona belongs to the preset.)`;\n      },\n    }));\n  }\n\n  if (!cfg.readonly) {\n    list.push(defineTool({\n      name: \"kura_remember\",\n      description:\n        `Write ONE fact into ${cfg.label}. This bypasses the distiller's evidence gate, so use ` +\n        `it only when the human explicitly asks for something to be remembered. One fact per ` +\n        `call, with its date in the text. The index line you give is a recognition trigger, not ` +\n        `a summary: it is read every single time, the body only when opened.`,\n      parameters: {\n        slug: { type: \"string\", description: \"kebab-case id\", required: true },\n        description: {\n          type: \"string\",\n          description: \"One index line — a recognition trigger, not a summary\",\n          required: true,\n        },\n        body: { type: \"string\", description: \"The fact itself\", required: true },\n        store: { type: \"string\", description: \"Which kura. Omit for the current one.\" },\n      },\n      output: TEXT,\n      async execute(args, exec) {\n        const to = target(args.store);\n        const d = await call(cfg, \"POST\", \"/remember\" + q(to),\n          { slug: args.slug, description: args.description, body: args.body }, exec?.signal);\n        return `${head(to)} ${JSON.stringify(d)}`;\n      },\n    }));\n  }\n\n  return state.bound ? list.map(withoutStoreParam) : list;\n}\n\n/**\n * Rule 3: read-only is enforced outside the tools. A monotonic guard cannot be\n * overturned by another listener, so the deployment stays read-only even if some other\n * plugin would rather allow the call.\n */\nfunction readonlyGuard(cfg) {\n  return (execution) => {\n    if (execution.name !== \"kura_remember\") return undefined;\n    return `${cfg.label} is read-only here. Memories enter through the distiller's evidence ` +\n      `gate (kura distill run / drain), not by a tool call.`;\n  };\n}\n\nfunction apply(ctx, config) {\n  const cfg = settle(config);\n  // Bound = pinned to one kura for this agent: the preset IS the mode switch.\n  const state = {\n    current: cfg.store,\n    bound: cfg.store !== \"\" && !cfg.allowSwitch,\n    map: emptyMap(cfg.store),\n    // selector → the store the server resolves it to; a mode's target does not move.\n    resolved: new Map(),\n  };\n  const cache = mapCache(cfg, state);\n  state.cache = cache;\n\n  for (const tool of tools(cfg, state)) {\n    ctx.effect(() => ctx.tools.register(tool), `distill-kura.${tool.name}`);\n  }\n  if (cfg.readonly) {\n    ctx.effect(() => ctx.tools.guard(readonlyGuard(cfg)), \"distill-kura.readonly-guard\");\n  }\n\n  if (cfg.prefill) {\n    // Synchronous by contract: hand back the cached string, never a Promise.\n    ctx.effect(\n      () =>\n        ctx.systemPrompt.section({\n          name: \"distill-kura:map\",\n          order: cfg.promptOrder,\n          text: () => cache.text(),   // arrow: keeps `this` = cache inside text()\n        }),\n      \"distill-kura.map-section\",\n    );\n    cache.refresh();                       // first fill, not awaited\n    const timer = setInterval(() => { cache.refresh(); }, cfg.refreshMs);\n    if (typeof timer.unref === \"function\") timer.unref();\n    ctx.effect(() => () => clearInterval(timer), \"distill-kura.map-refresh\");\n  }\n}\n\nexport { Config, apply, inject, name };\n"
    },
